exercises.solution:
const suma = 0.2 + 0.4;
console.log(suma, typeof suma);              // 0.6000000000000001 'number'
console.log(suma.toFixed(1), typeof suma.toFixed(1)); // '0.6' 'string'

const a = 17;
const b = 5;
console.log(a / b);            // 3.4
console.log(Math.floor(a / b)); // 3
console.log(a % b);             // 2

const tekst = "150";
const liczba = Number(tekst);
console.log(liczba, typeof liczba); // 150 'number'

function losowaOcena() {
  return Math.floor(Math.random() * 6) + 1;
}

console.log(losowaOcena());
console.log(losowaOcena());
console.log(losowaOcena());
// za kazdym razem losowa liczba calkowita od 1 do 6

console.log(Math.round(2.5));  // 3
console.log(Math.round(2.4));  // 2
console.log(Math.round(-2.5)); // -2 (nie -3!)
// Math.round(-2.5) zaskakuje wielu programistow - dla dokladnie .5
// przy liczbach ujemnych, JavaScript zaokragla W KIERUNKU dodatniej
// nieskonczonosci, nie 'od zera', wiec -2.5 staje sie -2, nie -3

function porownajZTolerancja(a, b) {
  return Math.abs(a - b) < 0.0001;
}

console.log(porownajZTolerancja(0.1 + 0.2, 0.3)); // true
console.log(0.1 + 0.2 === 0.3); // false - dla porownania z bledem zaokraglenia

function obliczRabat(cena, procent) {
  const wynik = cena - cena * (procent / 100);
  return Number(wynik.toFixed(2));
}

console.log(obliczRabat(199.99, 15)); // 169.99

function jestParzysta(n) {
  return n % 2 === 0;
}

console.log(jestParzysta(7));  // false
console.log(jestParzysta(8));  // true
console.log(jestParzysta(-4)); // true

const tekst = "  42  ";
console.log(Number(tekst)); // 42
// Number() automatycznie 'przycina' biale znaki z brzegow PRZED
// probą konwersji - w odroznieniu od dowolnego innego, niepoprawnego
// znaku (ktory dalby NaN), spacje na brzegach sa ignorowane

function bezpiecznaLiczba(wejscie, domyslna) {
  const wynik = Number(wejscie);
  return Number.isNaN(wynik) ? domyslna : wynik;
}

console.log(bezpiecznaLiczba("123", 0)); // 123
console.log(bezpiecznaLiczba("abc", 0)); // 0

function podzielNaGrupy(elementy, rozmiarGrupy) {
  const grupy = Math.floor(elementy / rozmiarGrupy);
  const reszta = elementy % rozmiarGrupy;
  return { grupy, reszta };
}

console.log(podzielNaGrupy(23, 5)); // { grupy: 4, reszta: 3 }

function losowyElement(tablica) {
  const indeks = Math.floor(Math.random() * tablica.length);
  return tablica[indeks];
}

console.log(losowyElement(["a", "b", "c", "d"])); // losowy element z tablicy

function ograniczDoZakresu(wartosc, min, max) {
  return Math.max(min, Math.min(max, wartosc));
}

console.log(ograniczDoZakresu(150, 0, 100)); // 100
console.log(ograniczDoZakresu(-10, 0, 100)); // 0
console.log(ograniczDoZakresu(50, 0, 100));  // 50

function obliczBMI(waga, wzrostCm) {
  const wzrostM = wzrostCm / 100;
  const bmi = waga / (wzrostM ** 2);
  return Number(bmi.toFixed(1));
}

console.log(obliczBMI(70, 175)); // 22.9

function sumaCyfr(liczba) {
  const cyfry = String(liczba).split("");
  let suma = 0;
  for (let i = 0; i < cyfry.length; i++) {
    suma = suma + Number(cyfry[i]);
  }
  return suma;
}

console.log(sumaCyfr(12345)); // 15

function procentZmiany(staraWartosc, nowaWartosc) {
  const zmiana = ((nowaWartosc - staraWartosc) / staraWartosc) * 100;
  return Number(zmiana.toFixed(1));
}

console.log(procentZmiany(200, 250)); // 25

function jestWTrojkacie(a, b, c) {
  const najdluzszy = Math.max(a, b, c);
  const sumaPozostalych = a + b + c - najdluzszy;
  return sumaPozostalych > najdluzszy;
}

console.log(jestWTrojkacie(3, 4, 5));  // true
console.log(jestWTrojkacie(1, 1, 10)); // false

function zaokraglijDoWielokrotnosci(liczba, wielokrotnosc) {
  return Math.round(liczba / wielokrotnosc) * wielokrotnosc;
}

console.log(zaokraglijDoWielokrotnosci(23, 5)); // 25

